const mysql = require("mysql2");
const pool = mysql.createPool({ /* ... */ });

function getOrder(orderId, cb) {
  // Fetch an order by id.
  const sql = `SELECT * FROM orders WHERE id = ${orderId}`;
  pool.query(sql, cb);
}

